mapper.select:
SELECT id, type, name, type_name, icon, status, version, minutes, tip, published_at, published_by, created_at, updated_at FROM questionnaire
(name LIKE CONCAT('%', #{keyword}, '%') OR type_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY created_at DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE questionnaire_version
SET status = #{status}, published_at = #{publishedAt}, published_by = #{publishedBy}
WHERE id = #{id}

mapper.select:
SELECT id, question_id, text, scores_json, sort_order, created_at FROM question_option WHERE question_id IN
#{qid}
ORDER BY question_id ASC, sort_order ASC
